(r, big) => {
    const N = big ? 20000 : r.int(1, 12);
    const names = big ? ["a", "b", "c", "d", "e", "f", "g", "h"] : ["a", "b", "c"];
    const maxDepth = big ? 40 : 4;
    const root = { kids: new Map(), d: 0 };
    const all = [root];
    const size = t => { let s = 1; for (const k of t.kids.values()) s += size(k); return s; };
    const clone = (t, d) => { const c = { kids: new Map(), d }; for (const [k, v] of t.kids) c.kids.set(k, clone(v, d + 1)); return c; };
    const reg = t => { all.push(t); for (const v of t.kids.values()) reg(v); };
    let guard = 0;
    while (all.length - 1 < N && guard++ < N * 20) {
      const p = r.pick(all);
      if (p.d >= maxDepth) continue;
      const free = names.filter(x => !p.kids.has(x));
      if (!free.length) continue;
      let node = { kids: new Map(), d: p.d + 1 };
      // often copy an existing small subtree, so twins actually appear
      if (all.length > 1 && r.bool(0.35)) {
        const src = all[r.int(1, all.length - 1)];
        if (size(src) <= (big ? 30 : 4)) node = clone(src, p.d + 1);
      }
      p.kids.set(r.pick(free), node);
      reg(node);
    }
    const out = [];
    const walk = (t, path) => { for (const [k, v] of t.kids) { const q = [...path, k]; out.push(q); walk(v, q); } };
    walk(root, []);
    return [r.shuffle(out)];
  }

