function pruneTwins(paths: string[][]): string[][] {
  type Node = { kids: Map<string, Node>; gone: boolean };
  const root: Node = { kids: new Map(), gone: false };
  for (const p of paths) {
    let cur = root;
    for (const name of p) {
      if (!cur.kids.has(name)) cur.kids.set(name, { kids: new Map(), gone: false });
      cur = cur.kids.get(name)!;
    }
  }
  const same = (x: Node, y: Node): boolean => {
    if (x.kids.size !== y.kids.size) return false;
    for (const [k, v] of x.kids) {
      const w = y.kids.get(k);
      if (!w || !same(v, w)) return false;
    }
    return true;
  };
  const nodes: Node[] = [];
  const collect = (t: Node) => { for (const v of t.kids.values()) { nodes.push(v); collect(v); } };
  collect(root);
  for (let i = 0; i < nodes.length; i++)
    for (let j = i + 1; j < nodes.length; j++)
      if (nodes[i].kids.size > 0 && same(nodes[i], nodes[j])) nodes[i].gone = nodes[j].gone = true;
  const out: string[][] = [];
  const walk = (t: Node, path: string[]) => {
    for (const [k, v] of t.kids) {
      if (v.gone) continue;
      const q = [...path, k];
      out.push(q);
      walk(v, q);
    }
  };
  walk(root, []);
  return out;
}

