class Solution:
    def pruneTwins(self, paths: List[List[str]]) -> List[List[str]]:
        root = {}
        for p in paths:
            cur = root
            for name in p:
                cur = cur.setdefault(name, {})

        def same(x, y):
            if len(x) != len(y):
                return False
            return all(k in y and same(v, y[k]) for k, v in x.items())

        nodes = []
        def collect(t):
            for v in t.values():
                nodes.append(v)
                collect(v)
        collect(root)
        gone = set()
        for i in range(len(nodes)):
            for j in range(i + 1, len(nodes)):
                if nodes[i] and same(nodes[i], nodes[j]):
                    gone.add(id(nodes[i]))
                    gone.add(id(nodes[j]))
        out = []
        def walk(t, path):
            for k, v in t.items():
                if id(v) in gone:
                    continue
                q = path + [k]
                out.append(q)
                walk(v, q)
        walk(root, [])
        return out

