function pruneTwins(paths: string[][]): string[][] {
  type Node = { kids: Map<string, Node>; sig: string };
  const root: Node = { kids: new Map(), sig: "" };
  for (const p of paths) {
    let cur = root;
    for (const name of p) {
      if (!cur.kids.has(name)) cur.kids.set(name, { kids: new Map(), sig: "" });
      cur = cur.kids.get(name)!;
    }
  }
  const count = new Map<string, number>();
  const sign = (t: Node): string => {
    const parts: string[] = [];
    for (const name of [...t.kids.keys()].sort()) parts.push(name + "(" + sign(t.kids.get(name)!) + ")");
    t.sig = parts.join("");
    if (t.sig) count.set(t.sig, (count.get(t.sig) ?? 0) + 1);
    return t.sig;
  };
  sign(root);
  const out: string[][] = [];
  const walk = (t: Node, path: string[]) => {
    for (const [k, v] of t.kids) {
      if (v.sig && count.get(v.sig)! > 1) continue; // twin: drop it and everything below
      path.push(k);
      out.push([...path]);
      walk(v, path);
      path.pop();
    }
  };
  walk(root, []);
  return out;
}

